import math


class LayeredTextPlan:
    def __init__(self, layers, activation, layout, regularization=0.0):
        if isinstance(layers, bool) or not isinstance(layers, int):
            raise TypeError("layers must be an integer")
        if layers not in {2, 4, 6, 8}:
            raise ValueError("unsupported layer count")
        if not isinstance(activation, str):
            raise TypeError("activation must be a string")
        if activation not in {"pre", "post"}:
            raise ValueError("unsupported activation")
        if not isinstance(layout, str):
            raise TypeError("layout must be a string")
        if layout not in {"forward", "reverse"}:
            raise ValueError("unsupported layout")
        if isinstance(regularization, bool) or not isinstance(
            regularization, (int, float)
        ):
            raise TypeError("regularization must be numeric")
        if not math.isfinite(regularization) or regularization < 0:
            raise ValueError("regularization must be finite and non-negative")

        self.layers = layers
        self.activation = activation
        self.layout = layout
        self.regularization = float(regularization)

    def build(self, tokens):
        if not isinstance(tokens, list):
            raise TypeError("tokens must be a list")
        if any(not isinstance(token, str) for token in tokens):
            raise TypeError("tokens must contain only strings")

        values = list(tokens)
        if self.layout == "reverse":
            values.reverse()

        for number in range(1, self.layers + 1):
            if self.activation == "pre":
                values = [f"({value})L{number}" for value in values]
            else:
                values = [f"({value})L{number}" for value in values]
        return values

    def loss(self, predicted, expected):
        if not isinstance(predicted, list) or not isinstance(expected, list):
            raise TypeError("predicted and expected must be lists")
        if len(predicted) != len(expected):
            raise ValueError("predicted and expected must have equal lengths")
        if not predicted:
            raise ValueError("loss requires at least one value")

        values = predicted + expected
        if any(
            isinstance(value, bool) or not isinstance(value, (int, float))
            for value in values
        ):
            raise TypeError("loss values must be numeric")
        if any(not math.isfinite(value) for value in values):
            raise TypeError("loss values must be finite")

        mse = sum((left - right) ** 2 for left, right in zip(predicted, expected))
        mse /= len(predicted)
        penalty = self.regularization * sum(
            number * number for number in range(1, self.layers + 1)
        )
        return mse + penalty

    def parameters(self, fine_tune=False):
        if not isinstance(fine_tune, bool):
            raise TypeError("fine_tune must be a boolean")
        numbers = [self.layers] if fine_tune else range(1, self.layers + 1)
        return [
            name
            for number in numbers
            for name in (f"layer{number}.weight", f"layer{number}.bias")
        ]

